<?php
if(!defined('ABSPATH'))exit(1);
$tester=new WordPressNewsBot\SourceConnectionTester();$errors=[];
foreach([['https://feed.test/rss.xml?category=fixture','RSS 2.0'],['https://feed.test/atom.xml','Atom'],['https://feed.test/rdf.xml','RSS 1.0/RDF'],['https://feed.test/generic.xml','RSS 2.0'],['https://www.feed.test/redirect','RSS 2.0']]as[$url,$type]){try{$result=$tester->test($url,['feed.test']);if($result['feed_type']!==$type||$result['item_count']!==1)$errors[]='success:'.$url;}catch(Throwable$e){$errors[]='success:'.$url.':'.get_class($e).':'.($e instanceof WordPressNewsBot\SourceTestException?$e->resultCode:'exception');}}
foreach([['https://feed.test/empty','body_empty'],['https://feed.test/broken','xml_invalid'],['https://feed.test/blocked','content_type_invalid'],['https://feed.test/rate-limited','http_status_invalid'],['https://feed.test/server-error','http_status_invalid'],['https://feed.test/private-redirect','redirect_blocked']]as[$url,$code]){try{$tester->test($url,['feed.test']);$errors[]='failure-not-raised:'.$url;}catch(WordPressNewsBot\SourceTestException$e){if($e->resultCode!==$code)$errors[]='failure-code:'.$url.':'.$e->resultCode;}}
if($errors){fwrite(STDERR,implode("\n",$errors)."\n");exit(1);}echo json_encode(['success_cases'=>5,'failure_cases'=>6,'copyrighted_content'=>false])."\n";
